function serializeOptions(options) {
  if (
    options === null ||
    typeof options !== "object" ||
    (Object.getPrototypeOf(options) !== Object.prototype &&
      Object.getPrototypeOf(options) !== null)
  ) {
    throw new TypeError("options must be an ordinary object");
  }

  function encodeRFC3986(value) {
    return encodeURIComponent(value).replace(/[!'()*]/g, function (char) {
      return "%" + char.charCodeAt(0).toString(16).toUpperCase();
    });
  }

  var pairs = [];

  for (var key of Object.keys(options)) {
    var value = options[key];

    if (value === undefined) {
      continue;
    }

    var stringValue;

    if (value === null) {
      stringValue = "";
    } else if (typeof value === "string") {
      stringValue = value;
    } else if (typeof value === "number" && Number.isFinite(value)) {
      stringValue = String(value);
    } else if (typeof value === "boolean") {
      stringValue = String(value);
    } else {
      throw new TypeError("invalid option value");
    }

    pairs.push([encodeRFC3986(key), encodeRFC3986(stringValue)]);
  }

  pairs.sort(function (a, b) {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    if (a[1] < b[1]) return -1;
    if (a[1] > b[1]) return 1;
    return 0;
  });

  return pairs.map(function (pair) {
    return pair[0] + "=" + pair[1];
  }).join("&");
}
